"""Northbound Goods storefront installer.  Run from the repo root:   python apply_storefront.py
Safe to re-run. Updates the storefront section of index.html (your chat-widget markup is left as it is), writes the store pages,
scripts and styles, and copies product photos from frontend/images/products into backend/app/static/images/products."""
import base64, zlib, os, re, sys, shutil
D = lambda s: zlib.decompress(base64.b64decode(s)).decode()
BLOCK, CSS, PJS, SJS, README = D(""), D(""), D(""), D(""), D("")
VJS, VCSS = "83eeed", "e2aa26"
PAGES = {"shop.html": ("shop", "Shop"), "product.html": ("product", "Product"), "cart.html": ("cart", "Your bag"), "checkout.html": ("checkout", "Checkout"), "order.html": ("order", "Order")}

def patch_index(s, path):
    if "<!-- Northbound Goods" in s:
        a = s.index("  <!-- Northbound Goods"); m = re.search(r"\n[ \t]*<!-- Chat widget -->", s[a:])
        if not m: sys.exit("Chat widget comment not found in " + path)
        b = a + m.start() + 1
    elif "<!-- Placeholder storefront" in s:
        a = s.index("  <!-- Placeholder storefront"); b = s.index("</main>", a) + len("</main>\n")
    else:
        sys.exit("Could not find the storefront section in " + path)
    s = s[:a] + BLOCK + s[b:]
    s = re.sub(r'\n?<link rel="stylesheet" href="storefront\.css[^"]*">', "", s)
    s = re.sub(r'(<link rel="stylesheet" href="ui-polish\.css[^"]*">)', r'\1\n<link rel="stylesheet" href="storefront.css?v=' + VCSS + '">', s, count=1)
    s = re.sub(r"<title>[^<]*</title>", "<title>Northbound Goods \u2014 Outerwear, Footwear, Essentials &amp; Accessories</title>", s, count=1)
    if "family=Jost" not in s: s = s.replace("&display=swap", "&family=Jost:wght@400;500;600&display=swap", 1)
    s = s.replace("Wrennon Agent", "Northbound Support").replace('aria-label="Wrennon customer support chat"', 'aria-label="Northbound Goods customer support chat"')
    s = re.sub(r"<body(?![^>]*data-page)([^>]*)>", r'<body data-page="home"\1>', s, count=1)
    s = re.sub(r'\n?<script src="(?:products|storefront)\.js[^"]*"></script>', "", s)
    s = s.replace("</body>", '<script src="products.js?v=' + VJS + '"></script>\n<script src="storefront.js?v=' + VJS + '"></script>\n</body>', 1)
    return s

def make_page(s, page, title):
    a = s.index("<!-- Northbound Goods"); a = s.rfind("\n", 0, a) + 1
    m = re.search(r"\n[ \t]*<!-- Chat widget -->", s[a:]); b = a + m.start() + 1
    t = s[:a] + '  <div class="sf" id="sf-root"></div>\n\n' + s[b:]
    t = t.replace('data-page="home"', 'data-page="%s"' % page, 1)
    return re.sub(r"<title>[^<]*</title>", "<title>%s \u2014 Northbound Goods</title>" % title, t, count=1)

def w(path, text):
    with open(path, "w", encoding="utf-8", newline="\n") as f: f.write(text)

ok = False
targets = [t for t in ("frontend", os.path.join("backend", "app", "static")) if os.path.exists(os.path.join(t, "index.html"))]
if not targets: sys.exit("Run from the repo root (folder containing 'frontend' and 'backend').")
for t in targets:
    p = os.path.join(t, "index.html")
    s = patch_index(open(p, encoding="utf-8").read(), p)
    w(p, s); print("updated:", p)
    for name, (page, title) in PAGES.items(): w(os.path.join(t, name), make_page(s, page, title))
    w(os.path.join(t, "storefront.css"), CSS); w(os.path.join(t, "products.js"), PJS); w(os.path.join(t, "storefront.js"), SJS)
    os.makedirs(os.path.join(t, "images", "products"), exist_ok=True)
    if not os.path.exists(os.path.join(t, "images", "products", "README.txt")): w(os.path.join(t, "images", "products", "README.txt"), README)
    print("written: 5 store pages + storefront.css/js + products.js in", t)
if len(targets) == 2:
    src, dst = os.path.join("frontend", "images", "products"), os.path.join("backend", "app", "static", "images", "products")
    n = 0
    for f in os.listdir(src):
        if f.lower().endswith((".jpg", ".jpeg", ".png", ".webp")): shutil.copy2(os.path.join(src, f), os.path.join(dst, f)); n += 1
    print("photos synced to backend/app/static:", n)
print("Done. Hard-refresh the browser (Ctrl+Shift+R). Product photos go in frontend/images/products (see README.txt there).")
